import '../../data/models/student_model.dart';
import '../../features/majors/data/major_model.dart';
class RecommendationMatch { const RecommendationMatch({required this.major,required this.percentage,required this.reasons,required this.strengths,required this.weaknesses}); final MajorModel major; final double percentage; final List<String> reasons,strengths,weaknesses; }
class RecommendationService { const RecommendationService(); List<RecommendationMatch> recommend({required StudentModel student,required Iterable<MajorModel> majors,Map<String,double> assessmentScores=const {}}) { return majors.map((major) { final skillMatches=major.requiredSkillIds.where(student.skillIds.contains).length; final interestMatches=major.interests.where(student.interestIds.contains).length; final skillScore=major.requiredSkillIds.isEmpty ? 20 : 40*skillMatches/major.requiredSkillIds.length; final interestScore=major.interests.isEmpty ? 20 : 30*interestMatches/major.interests.length; final academicScore=student.gpa == null ? 0 : (student.gpa!/5*20).clamp(0,20); final assessmentScore=assessmentScores.values.isEmpty ? 0 : (assessmentScores.values.reduce((a,b)=>a+b)/assessmentScores.length).clamp(0,10); final percentage=(skillScore+interestScore+academicScore+assessmentScore).clamp(0,100).toDouble(); final reasons=<String>[if(skillMatches>0)'تتوافق مهاراتك مع متطلبات التخصص',if(interestMatches>0)'ميولك مرتبطة بهذا المجال',if(student.gpa != null)'مستواك الأكاديمي مدعوم في التحليل']; return RecommendationMatch(major:major,percentage:percentage,reasons:reasons,strengths:skillMatches>0?['مهارات مرتبطة بالتخصص']:const [],weaknesses:skillMatches==major.requiredSkillIds.length?const []:['يمكن تطوير المهارات المطلوبة']); }).toList()..sort((a,b)=>b.percentage.compareTo(a.percentage)); } }
